INSERT INTO evaluations (id, ova_id, type, config) VALUES
  ('c0a7e17d-0000-4000-8350-000000000001', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a05', 'autoevaluacion', '{"questions":[{"id":"e1","correct_answer":"c","feedback_incorrect":"El patrocinador firma el acta: autoriza el proyecto y le da autoridad al director."},{"id":"e2","correct_answer":"b","feedback_incorrect":"Mucho poder y poco interés: mantener satisfecho, sin saturarlo de información."},{"id":"e3","correct_answer":"b","feedback_incorrect":"El plan para la dirección integra las líneas base de alcance, cronograma y costos y los planes de cada área."},{"id":"e4","correct_answer":"a","feedback_incorrect":"La elaboración progresiva detalla el plan a medida que se conoce más."},{"id":"e5","correct_answer":"c","feedback_incorrect":"Un interesado es cualquier persona u organización que afecta el proyecto o se ve afectada por él."}]}'::jsonb),
  ('c0a7e17d-0000-4000-8310-000000000001', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a01', 'autoevaluacion', '{"questions":[{"id":"e1","correct_answer":"b","feedback_incorrect":"La línea base del alcance son el enunciado, la EDT y su diccionario aprobados."},{"id":"e2","correct_answer":"b","feedback_incorrect":"La regla del 100 % pide que la EDT cubra todo el trabajo y nada más."},{"id":"e3","correct_answer":"c","feedback_incorrect":"La EDT se orienta a entregables: usa sustantivos, no verbos ni fechas."},{"id":"e4","correct_answer":"a","feedback_incorrect":"Agregar funciones que nadie pidió es enchapado en oro."},{"id":"e5","correct_answer":"c","feedback_incorrect":"La decisión formal sobre un cambio corresponde al Comité de Control de Cambios."}]}'::jsonb),
  ('c0a7e17d-0000-4000-8320-000000000001', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a02', 'autoevaluacion', '{"questions":[{"id":"e1","correct_answer":"b","feedback_incorrect":"La ruta crítica es la secuencia más larga de actividades dependientes y fija la duración mínima."},{"id":"e2","correct_answer":"b","feedback_incorrect":"La holgura total es el inicio tardío menos el inicio temprano: 9 − 6 = 3 semanas."},{"id":"e3","correct_answer":"c","feedback_incorrect":"El retraso consume la holgura y solo el exceso (3 − 2 = 1 semana) llega al final del proyecto."},{"id":"e4","correct_answer":"c","feedback_incorrect":"Agregar recursos a una actividad crítica para acortarla es intensificación."},{"id":"e5","correct_answer":"a","feedback_incorrect":"La ejecución rápida solapa actividades en secuencia y su principal riesgo es el retrabajo."}]}'::jsonb),
  ('c0a7e17d-0000-4000-8330-000000000001', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a03', 'autoevaluacion', '{"questions":[{"id":"e1","correct_answer":"b","feedback_incorrect":"CPI = EV / AC = 100 / 125 = 0,80: cada peso gastado rinde 80 centavos de trabajo."},{"id":"e2","correct_answer":"b","feedback_incorrect":"El SPI compara EV con PV: un valor de 1,10 indica que se avanza 10 % más rápido de lo planeado."},{"id":"e3","correct_answer":"d","feedback_incorrect":"EAC = BAC / CPI = 480 / 0,80 = $600 millones."},{"id":"e4","correct_answer":"b","feedback_incorrect":"El valor ganado (EV) es el trabajo terminado expresado en dinero del presupuesto."},{"id":"e5","correct_answer":"b","feedback_incorrect":"CV negativa es sobrecosto y SV positiva es adelanto: se está comprando velocidad con más gasto."}]}'::jsonb),
  ('c0a7e17d-0000-4000-8340-000000000001', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a04', 'autoevaluacion', '{"questions":[{"id":"e1","correct_answer":"c","feedback_incorrect":"Probabilidad × impacto = 2 × 3 = 6, que está en la zona de prioridad alta (6 a 9)."},{"id":"e2","correct_answer":"b","feedback_incorrect":"Trasladar el impacto a un tercero mediante un contrato o seguro es transferir."},{"id":"e3","correct_answer":"a","feedback_incorrect":"Cambiar el plan para eliminar la amenaza es evitar."},{"id":"e4","correct_answer":"c","feedback_incorrect":"Compartir, explotar y mejorar son estrategias para oportunidades."},{"id":"e5","correct_answer":"b","feedback_incorrect":"Cuando un riesgo ocurre deja de ser incierto: se convierte en un problema."}]}'::jsonb),
  ('c0a7e17d-0000-4000-8360-000000000001', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a06', 'autoevaluacion', '{"questions":[{"id":"e1","correct_answer":"c","feedback_incorrect":"Canales = n(n − 1) / 2 = 6 × 5 / 2 = 15."},{"id":"e2","correct_answer":"c","feedback_incorrect":"Cuando el equipo crea y cumple sus propias reglas está en normalización."},{"id":"e3","correct_answer":"b","feedback_incorrect":"Inspeccionar el producto para detectar defectos es controlar la calidad; gestionarla es prevenir en el proceso."},{"id":"e4","correct_answer":"d","feedback_incorrect":"I = informado: recibe información del avance, pero no participa en la decisión."},{"id":"e5","correct_answer":"c","feedback_incorrect":"La ejecución concentra la mayor parte del trabajo, el tiempo y el presupuesto."}]}'::jsonb),
  ('c0a7e17d-0000-4000-8370-000000000001', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a07', 'autoevaluacion', '{"questions":[{"id":"e1","correct_answer":"b","feedback_incorrect":"El Comité de Control de Cambios (CCB) aprueba, rechaza o difiere los cambios a las líneas base."},{"id":"e2","correct_answer":"b","feedback_incorrect":"Actuar antes de que ocurra el desvío es una acción preventiva."},{"id":"e3","correct_answer":"c","feedback_incorrect":"El comité decide con base en el análisis de impacto en alcance, tiempo, costo, calidad y riesgos."},{"id":"e4","correct_answer":"a","feedback_incorrect":"La gestión de la configuración registra una nueva versión de la línea base por cada cambio aprobado."},{"id":"e5","correct_answer":"c","feedback_incorrect":"Si el producto no cumple un requisito ya aprobado, es una reparación de defecto."}]}'::jsonb),
  ('c0a7e17d-0000-4000-8380-000000000001', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a08', 'autoevaluacion', '{"questions":[{"id":"e1","correct_answer":"b","feedback_incorrect":"Primero se aceptan formalmente los entregables; luego se transfieren a operación."},{"id":"e2","correct_answer":"c","feedback_incorrect":"Una buena lección tiene situación, impacto, causa y una recomendación accionable."},{"id":"e3","correct_answer":"b","feedback_incorrect":"Al liberar al equipo las personas se van a otros proyectos y el conocimiento se pierde."},{"id":"e4","correct_answer":"c","feedback_incorrect":"Los beneficios se materializan después; el informe final define quién y cuándo los mide."},{"id":"e5","correct_answer":"a","feedback_incorrect":"Verificar, pagar y liberar al proveedor es el cierre del contrato (adquisiciones)."}]}'::jsonb)
